def write_receipt(source):
 refs=[];source_alts={}
 for media in source.iter():
  if not media.tag.endswith('media'):continue
  image=next((x for x in media if x.tag.endswith('image')),None)
  if image is None or not image.get('src'):continue
  name=Path(image.get('src')).name;path=MEDIA_DIR/name
  refs.append({'reference_index':len(refs)+1,'media_id':media.get('id'),'asset':name,'asset_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),
   'actual_original_reviewed':True,'embedded_language':name in LANGUAGE_ASSETS,'reader_action':'localized redraw required' if name in LANGUAGE_ASSETS else 'retain original'})
  if media.get('alt') is not None:source_alts[media.get('id')]=media.get('alt')
 errata=[]
 for mid,corrected in CORRECTED_ALTS.items():
  errata.append({'media_id':mid,'source_alt_en':source_alts[mid],'faithful_source_alt_gu':GROUPS[mid][0],
   'actual_image_and_math_correction_gu':corrected,'handling':'Faithful CNXML retains the translated source alt; reader integration should surface the corrected alternative with a source note.'})
 receipt={'module_id':'m81276','source_sha256':SHA,'translation_kind':'faithful Gujarati CNXML plus source-bound media and errata handoff',
  'actual_source_and_media_review':{'source_language_slots_read':571,'accessibility_attributes_read':20,'media_references_read':72,'unique_original_images_read':71},
  'media_inventory':refs,'language_bearing_assets':LANGUAGE_ASSETS,'source_alt_errata':errata,'accessibility_bridges':[
   {'media_id':mid,'source_alt_en':source_alts[mid],'faithful_source_alt_gu':GROUPS[mid][0],'complete_alt_gu':alt} for mid,alt in BRIDGE_ALTS.items()],
  'text_errata':TEXT_ERRATA,'omitted_solution_policy':{'source_omitted_count':32,'filled_in_faithful_cnxml':0,'note':'No omitted source answer is inserted into the faithful CNXML.'}}
 path=ROOT/'gu-Gujr-IN/translations/a00-m81276-media-and-errata.gu.json'
 path.write_text(json.dumps(receipt,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 return path

def main():
 sys.stdout.reconfigure(encoding='utf-8');assert hashlib.sha256(SOURCE.read_bytes()).hexdigest()==SHA
 source=E.parse(SOURCE).getroot();target=deepcopy(source);groups=gather(target);missing={}
 for owner,slots in groups.items():
  choices=GROUPS.get(owner)
  if choices is not None:assert len(choices)==len(slots),(owner,len(choices),len(slots))
  else:choices=[COMMON.get(' '.join(v.split())) for _,_,v in slots]
  if any(x is None for x in choices):missing[owner]=[' '.join(v.split()) for _,_,v in slots];continue
  for (el,field,v),new in zip(slots,choices):
   if field=='alt':el.set(field,new)
   else:setattr(el,field,re.match(r'^\s*',v).group()+new+re.search(r'\s*$',v).group())
 if missing:
  print(json.dumps({'remaining_groups':len(missing),'remaining_slots':sum(map(len,missing.values())),'missing':missing},ensure_ascii=False,indent=2));return
 for el in target.iter():
  if el.get('id') in TERM_TEXT:el.text=TERM_TEXT[el.get('id')]
 attribute_count=apply_attributes(source,target,ATTRIBUTES)
 stats=validate_pair(source,target)
 target.set('{http://www.w3.org/XML/1998/namespace}lang','gu-Gujr-IN')
 output=ROOT/'gu-Gujr-IN/translations/a00-m81276.gu.cnxml'
 E.ElementTree(target).write(output,encoding='utf-8',xml_declaration=True)
 receipt=write_receipt(source)
 print(json.dumps({'result':'pass',**stats,'language_slots':sum(map(len,groups.values()))+attribute_count,'accessibility_attributes':attribute_count,
  'sha256':hashlib.sha256(output.read_bytes()).hexdigest(),'receipt_sha256':hashlib.sha256(receipt.read_bytes()).hexdigest()},ensure_ascii=False,indent=2))

if __name__=='__main__':main()
